import functools, time

def retry(times=3, delay=0.5):
    def deco(fn):
        @functools.wraps(fn)
        def wrap(*args, **kwargs):
            for i in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception:
                    if i == times - 1:
                        raise
                    time.sleep(delay * 2 ** i)
        return wrap
    return deco

